    int parent[m];
    for (int i = 0; i < m; i++) {
        parent[i] = i;
    }

    int rank[m] = {0};

    vector<int> included(n, 0);
    for (int i = 0; i < n; i++) {
        if (edges[i][0] == edges[i][1]) {
            continue;
        }
        if (find(edges[i][0], parent) != find(edges[i][1], parent)) {
            unionSet(edges[i][0], edges[i][1], parent, rank);
            included[i] = 1;
        }
    }

    int result = 1;
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (included[i]) {
            count++;
        }
    }

    for (int i = 0; i < count; i++) {
        result = (1LL * result * 2) % mod;
    }

