const int MOD = 1e9 + 7;

int countGoodArrays(int n, vector<int>& c, vector<int>& b, int x) {
    vector<long double> d(n);
    d[0] = x;
    for (int i = 1; i < n; i++) {
        d[i] = d[i - 1] + b[i - 1];
    }

    long long count = 0;
    function<void(int, long long)> dfs = [&](int i, long long sum) {
        if (i == n) {
            if (sum >= 0) {
                count = (count + 1) % MOD;
            }
            return;
        }
        for (int j = 0; j <= c[i]; j++) {
            if (sum + j - d[i] >= 0) {
                dfs(i + 1, sum + j - d[i]);
            }
        }
    };

    dfs(0, 0);
    return count;
}

