std::string convertToBase(int number, int base) {
    if (number == 0) return "0";
    std::string result = "";
    while (number > 0) {
        int remainder = number % base;
        if (remainder < 10) result = std::to_string(remainder) + result;
        else result = char('A' + remainder - 10) + result;
        number = number / base;
    }
    return result;
}

