    for (int i = 0; i < n; i++) {
        cin >> a[i] >> b[i];
    }
    int ans = find_smallest_integer(a[0], b[0]);
    for (int i = 1; i < n; i++) {
        int x = find_smallest_integer(a[i], b[i]);
        if (x == -1) {
            ans = -1;
            break;
        }
        int lcm_ab = lcm(a[i], a[0]);
        if (lcm_ab > 1e18) {
            ans = -1;
            break;
        }
        int y = find_smallest_integer(lcm_ab, b[0]);
        if (y == -1) {
            ans = -1;
            break;
        }
        if (x != y) {
            ans = -1;
            break;
        }
        a[0] = lcm_ab;
    }
    if (ans != -1) {
        cout << ans % mod << '\n';
    } else {
        cout << -1 << '\n';
    }
    return 0;
}

