vector<int> values;

void setValues(int PLUS, int MINUS) {
    int diff = 0;
    if (PLUS != 0 && MINUS != 0) {
        diff = PLUS - MINUS;
    } else if (PLUS != 0) {
        diff = PLUS;
    } else if (MINUS != 0) {
        diff = -MINUS;
    }

    int plusSum = 0;
    int minusSum = 0;
    for (int i = 0; i < plusCount; i++) {
        if (i == plusCount - 1) {
            plusSum += n - plusSum;
        } else {
            plusSum += 1;
        }
    }
    for (int i = 0; i < minusCount; i++) {
        if (i == minusCount - 1) {
            minusSum += n - minusSum;
        } else {
            minusSum += 1;
        }
    }

    if (diff >= 0) {
        int maxVal = plusSum + minusSum;
        if (maxVal < n) {
            plusSum += n - maxVal;
        }
    } else {
        int maxVal = plusSum + minusSum;
        if (maxVal < n) {
            minusSum += n - maxVal;
        }
    }

    int val = 1;
    for (int i = 0; i < plusCount - 1; i++) {
        values.push_back(val);
        val++;
    }
    if (plusCount > 0) {
        values.push_back(plusSum - (plusCount - 1));
    }
    for (int i = 0; i < minusCount - 1; i++) {
        values.push_back(val);
        val++;
    }
    if (minusCount > 0) {
        values.push_back(minusSum - (minusCount - 1));
    }
}

void check() {
    for (int i = 0; i < plusCount; i++) {
        int curVal = n;
        while (curVal > 0) {
            setValues(i + 1, plusCount - i - 1);
            int sum = 0;
            int cur = 0;
            for (int j = 0; j < values.size(); j++) {
                if (j % 2 == 0) {
                    sum += values[j];
                } else {
                    sum -= values[j];
                }
            }
            if (sum == n) {
                cout << "Possible" << endl;
                for (int j = 0; j < values.size(); j++) {
                    cout << values[j];
                    if (j < values.size() - 1) {
                        if (j % 2 == 0) {
                            cout << " + ";
                        } else {
                            cout << " - ";
                        }
                    }
                }
                cout << " = " << n << endl;
                return;
            }
            curVal--;
            values.clear();
        }
    }
}

