}

void dfs(int u, int rt, long long &sum) {
    sz[u] = w[u];
    sum += w[u];
    for (int v : g[u]) {
        if (v != rt) {
            dfs(v, rt, sum);
            sz[u] += sz[v];
        }
    }
}

