    vector<pair<long long, long long>> v2 = {{x2, y2}, {y2, -x2}, {-x2, -y2}, {-y2, x2}};

    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            if (check(v1[i].first, v1[i].second, v2[j].first, v2[j].second, x3, y3)) {
                cout << "YES" << endl;
                return 0;
            }
        }
    }
    cout << "NO" << endl;
    return 0;
}

