    path2.push_back(d);

    if (path1.size() > n || path2.size() > n) {
        cout << -1 << endl;
        return 0;
    }

    set<pair<int, int>> roads;
    for (int i = 0; i < path1.size() - 1; ++i) {
        int x = path1[i];
        int y = path1[i + 1];
        if (x > y) {
            swap(x, y);
        }
        roads.insert(make_pair(x, y));
    }

    for (int i = 0; i < path2.size() - 1; ++i) {
        int x = path2[i];
        int y = path2[i + 1];
        if (x > y) {
            swap(x, y);
        }
        roads.insert(make_pair(x, y));
    }

    if (roads.size() > k) {
        cout << -1 << endl;
    } else {
        printPath(path1);
        printPath(path2);
    }

    return 0;
}

