using namespace std;

const int MAX_N = 1005;
const long long INF = 1e18;

struct Edge {
    int v, w;
};

vector<Edge> adj[MAX_N];
long long d[MAX_N];
bool inQueue[MAX_N];

void dijkstra(int s) {
    for (int i = 0; i < MAX_N; i++) {
        d[i] = INF;
        inQueue[i] = false;
    }
    d[s] = 0;
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    pq.push({0, s});
    while (!pq.empty()) {
        int u = pq.top().second;
        pq.pop();
        inQueue[u] = false;
        for (const Edge& edge : adj[u]) {
            int v = edge.v;
            long long w = edge.w;
            if (d[u] + w < d[v]) {
                d[v] = d[u] + w;
                if (!inQueue[v]) {
                    pq.push({d[v], v});
                    inQueue[v] = true;
                }
            }
        }
    }
}

