                mp[ans.first]++;
            }
        }
    }
    pair<int, int> res = {0, 0};
    for (auto it = mp.rbegin(); it != mp.rend(); it++) {
        res = {it->first, it->second};
        break;
    }
    cout << res.first << " " << res.second << endl;
    return 0;
}

