const int mod = 1e9 + 7;

vector<int> parent(20), size(20);

int find(int x) {
    if (parent[x] != x) {
        parent[x] = find(parent[x]);
    }
    return parent[x];
}

void unionSet(int x, int y) {
    int rootx = find(x);
    int rooty = find(y);
    if (rootx != rooty) {
        if (size[rootx] > size[rooty]) {
            parent[rooty] = rootx;
        } else {
            parent[rootx] = rooty;
            if (size[rootx] == size[rooty]) {
                size[rooty]++;
            }
        }
    }
}

