            for (int i = n - 1; i >= 0; --i) {
                if (index >= 0) {
                    board[i][j] = column[index];
                    --index;
                } else {
                    board[i][j] = '.';
                }
            }
        }
    } else if (move == 'L') {
        for (int i = 0; i < n; ++i) {
