    double ans = 1e9;
    for (int i = 1; i <= a.back(); i++) {
        vector<double> cur(n);
        cur[0] = abs(i - a[0]) / (double)a[0];
        double mx = cur[0];
        for (int j = 1; j < n; j++) {
            double l = 1, r = 1e5;
            for (int k = 0; k < 100; k++) {
