    q.push({start, 0});
    dist[start] = 0;

    while (!q.empty()) {
        auto [u, w] = q.front();
        q.pop();

        for (const auto& edge : graph[u]) {
            if (edge.w > w && dist[edge.v] > w) {
                dist[edge.v] = w;
                q.push({edge.v, edge.w});
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    cin >> n >> m >> k;
    graph.resize(n);

    for (int i = 0; i < k; ++i) {
