using namespace std;

long long check(long long x, long long y) {
    if (y == 1) return 1;
    long long d = (x + y - 1) / y;
    if (x < y) {
        long long pos = x;
        long long diff = y - x;
        if ((diff % 2) == 0 && (diff / 2) <= (d - 1)) return diff / 2 + 1;
        else return 0;
    }
    if ((d * y) == x) return d;
    if ((x + y - 1) % y == 0) return d;
    if (((d - 1) * y) < x && ((d - 1) * y) + (d - 1) >= x) return d - 1;
    return 0;
}

int main() {
