void dfs(int v) {
    if (d[v] == 1) return;
    d[v] = 1;
    for (auto u : g[v]) {
        dfs(u);
        if (dp[u] == 0) dp[v] = 1;
        else if (dp[u] == -1) dp[v] = -1;
        else if (dp[u] == 1) {
            if (dp[v] != -1) dp[v] = 0;
        }
    }
    if (dp[v] != -1) dp[v] = d[v] = 0;
}

