#include <bits/stdc++.h>

using namespace std;

struct Character {
    int health, attack, defense, agility;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Character> characters(n + 1);
    for (int i = 0; i <= n; ++i) {
        cin >> characters[i].health >> characters[i].attack >> characters[i].defense >> characters[i].agility;
    }

    sort(begin(characters), end(characters), [](const Character& a, const Character& b) {
        return a.agility > b.agility;
    });

    vector<int> prefix(n + 1);
    for (int i = 1; i <= n; ++i) {
        prefix[i] = prefix[i - 1] + characters[i].attack - characters[0].defense;
    }

    vector<long long> dp(1 << n);
    for (int mask = 1; mask < (1 << n); ++mask) {
        int last = __builtin_ctz(mask);
        int totalDamage = prefix[last];
        if (mask == (1 << last)) {
            dp[mask] = totalDamage;
            continue;
        }
        dp[mask] = LLONG_MAX;
        for (int subMask = mask; subMask > 0; subMask = (subMask - 1) & mask) {
            int otherMask = mask ^ subMask;
            if (otherMask == 0) continue;
            dp[mask] = min(dp[mask], dp[subMask] + dp[otherMask] + totalDamage);
        }
        dp[mask] = min(dp[mask], dp[mask ^ (1 << last)] + totalDamage);
    }

    long long ans = dp.back();
    if (ans >= characters[0].health) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

#define rep(i, a, b) for(int i = a; i < (b); ++i)
#define all(x) begin(x), end(x)
#define sz(x) (int)(x).size()
typedef long long ll;
typedef pair<int, int> pii;
typedef vector<int> vi;
typedef vector<ll> vll;
typedef vector<pii> vpi;

const int MAXN = 50;
const int MAXM = 500;

struct Tag {
    string name;
    bool visible;
};

struct DML {
    string filename;
    vector<Tag> tags;
};

struct DS {
    string filename;
    map<string, vector<pair<string, bool>>> subroutines;
};

DML parseDML(string filename, string content) {
    DML dml;
    dml.filename = filename;
    vector<string> tokens;
    string token;
    for(char c : content) {
        if(c == '<' || c == '>') {
            if(!token.empty()) {
                tokens.push_back(token);
                token.clear();
            }
            token += c;
        } else {
            token += c;
        }
    }
    if(!token.empty()) {
        tokens.push_back(token);
    }
    vector<Tag> stack;
    for(string token : tokens) {
        if(token[0] == '<' && token[1] != '/') {
            string name = token.substr(1, token.size() - 2);
            Tag tag;
            tag.name = name;
            tag.visible = true;
            dml.tags.push_back(tag);
            stack.push_back(tag);
        } else if(token[0] == '<' && token[1] == '/') {
            string name = token.substr(2, token.size() - 3);
            stack.pop_back();
        }
    }
    return dml;
}

DS parseDS(string filename, string content) {
    DS ds;
    ds.filename = filename;
    map<string, vector<pair<string, bool>>> subroutines;
    vector<string> tokens;
    string token;
    for(char c : content) {
        if(c == '{' || c == '}') {
            if(!token.empty()) {
                tokens.push_back(token);
                token.clear();
            }
            token += c;
        } else {
            token += c;
        }
    }
    if(!token.empty()) {
        tokens.push_back(token);
    }
    for(size_t i = 0; i < tokens.size(); i += 3) {
        string subroutineName = tokens[i];
        string expressions = tokens[i + 1];
        vector<pair<string, bool>> expressionList;
        size_t pos = 0;
        while((pos = expressions.find(";")) != string::npos) {
            string expression = expressions.substr(0, pos);
            expressions.erase(0, pos + 1);
            size_t equalsPos = expression.find("=");
            size_t notPos = expression.find("!");
            string varName;
            bool negate = false;
            if(equalsPos != string::npos) {
                varName = expression.substr(0, equalsPos);
                if(notPos != string::npos && notPos < equalsPos) {
                    negate = true;
                }
            } else {
                varName = expression;
            }
            bool value = (expression.find("true") != string::npos);
            expressionList.push_back({varName, negate ? !value : value});
        }
        subroutines[subroutineName] = expressionList;
    }
    ds.subroutines = subroutines;
    return ds;
}

void applySubroutine(DML& dml, DS& ds, string subroutineName) {
    auto subroutine = ds.subroutines[subroutineName];
    for(auto& expression : subroutine) {
        string varName = expression.first;
        bool value = expression.second;
        for(auto& tag : dml.tags) {
            if(tag.name == varName) {
                tag.visible = value;
            }
        }
    }
}

void printDML(DML& dml, int width, int height) {
    vector<vector<char>> screen(height, vector<char>(width, '.'));
    int x = 0, y = 0;
    for(auto& tag : dml.tags) {
        if(tag.name == "br") {
            x = 0;
            y++;
        } else if(tag.name == "script") {
            continue;
        } else if(tag.visible) {
            string text = tag.name;
            for(size_t i = 0; i < text.size(); i++) {
                if(x >= width) {
                    x = 0;
                    y++;
                }
                if(y >= height) {
                    break;
                }
                screen[y][x] = text[i];
                x++;
            }
        }
    }
    for(int i = 0; i < height; i++) {
        for(int j = 0; j < width; j++) {
            cout << screen[i][j];
        }
        cout << endl;
    }
}

int main() {
    int N;
    cin >> N;
    vector<DML> dmls;
    vector<DS> ds;
    for(int i = 0; i < N; i++) {
        string filename, content;
        cin >> filename >> content;
        if(filename.find(".dml") != string::npos) {
            dmls.push_back(parseDML(filename, content));
        } else {
            ds.push_back(parseDS(filename, content));
        }
    }
    int M;
    cin >> M;
    for(int i = 0; i < M; i++) {
        int width, height, operations;
        string startFile;
        cin >> width >> height >> operations >> startFile;
        DML currentDML = *find_if(all(dmls), [&](DML& dml) { return dml.filename == startFile; });
        for(int j = 0; j < operations; j++) {
            int x, y;
            cin >> x >> y;
            for(auto& tag : currentDML.tags) {
                if(tag.name == "link") {
                    string linkFile = tag.name;
                    DML nextDML = *find_if(all(dmls), [&](DML& dml) { return dml.filename == linkFile + ".dml"; });
                    currentDML = nextDML;
                } else if(tag.name == "button") {
                    string subroutineName = tag.name;
                    applySubroutine(currentDML, ds[0], subroutineName);
                }
            }
        }
        printDML(currentDML, width, height);
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>
#include <limits>

struct Point {
    double x, y;
};

struct Circle {
    Point center;
    double radius;
};

double distance(const Point& p1, const Point& p2) {
    return std::sqrt(std::pow(p1.x - p2.x, 2) + std::pow(p1.y - p2.y, 2));
}

bool isInside(const Circle& circle, const Point& point) {
    return distance(circle.center, point) <= circle.radius;
}

bool isIntersecting(const Circle& circle, const Point& p1, const Point& p2) {
    double dx = p2.x - p1.x;
    double dy = p2.y - p1.y;
    double d = distance(p1, p2);
    double t = (dx * (circle.center.x - p1.x) + dy * (circle.center.y - p1.y)) / (d * d);
    t = std::max(0.0, std::min(1.0, t));
    Point nearestPoint = {p1.x + t * dx, p1.y + t * dy};
    return distance(circle.center, nearestPoint) <= circle.radius;
}

double getShortestPath(const std::vector<Circle>& circles, int D) {
    Point start = {25, 0};
    Point end = {25, 94};
    double shortestPath = std::numeric_limits<double>::max();

    for (int i = 0; i <= D; i++) {
        for (double x = 0; x <= 50; x += 0.1) {
            Point point = {x, 0};
            double pathLength = 0;
            int intersections = 0;
            bool isValidPath = true;

            for (const auto& circle : circles) {
                if (isInside(circle, point)) {
                    isValidPath = false;
                    break;
                }
            }

            if (!isValidPath) continue;

            while (point.y < 94) {
                Point nextPoint = {point.x, point.y + 0.1};
                bool intersecting = false;

                for (const auto& circle : circles) {
                    if (isIntersecting(circle, point, nextPoint)) {
                        intersecting = true;
                        intersections++;
                        break;
                    }
                }

                if (intersections > D) {
                    isValidPath = false;
                    break;
                }

                pathLength += distance(point, nextPoint);
                point = nextPoint;
            }

            if (isValidPath) {
                shortestPath = std::min(shortestPath, pathLength);
            }
        }
    }

    if (shortestPath == std::numeric_limits<double>::max()) {
        return -1;
    }

    return shortestPath;
}

int main() {
    int N, D;
    std::cin >> N >> D;

    std::vector<Circle> circles;
    circles.reserve(N);

    for (int i = 0; i < N; i++) {
        int x, y, radius;
        std::cin >> x >> y >> radius;
        circles.emplace_back(Circle{{static_cast<double>(x), static_cast<double>(y)}, static_cast<double>(radius)});
    }

    double shortestPath = getShortestPath(circles, D);
    std::printf("%.7f\n", shortestPath);

    return 0;
}

