const int mod = 1e9 + 7;

bool isPrime(int n) {
    if (n <= 1) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    for (int i = 3; i * i <= n; i += 2) {
        if (n % i == 0) return false;
    }
    return true;
}

bool check(int n, int i, int& p, unordered_map<int, int>& powers) {
    if (i < 0) return true;
    if (n % p == 0 && powers[p] == 0) {
        n /= p;
        powers[p]++;
        return check(n, i - 1, p, powers);
    }
    return false;
}

