        for (int j = 0; j < p; ++j) {
            cin >> A[i][j];
        }
    }

    vector<int> available(p, 0);
    for (int i = 0; i < n; ++i) {
        available[s[i] - 'a'] = 1;
    }

    string t = s;
    cout << bruteForce(t, 0, available) << endl;

    return 0;
}

