using namespace std;

const int MAXN = 100005;
const int MAXM = 100005;
const int INF = numeric_limits<int>::max();

struct Edge {
    int to, next, w;
};

Edge edges[MAXM * 2];
int head[MAXN], tot = 0;

void addEdge(int u, int v) {
    edges[++tot] = {v, head[u]};
    head[u] = tot;
}

int dis[MAXN][MAXN];

void floyd(int n) {
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            dis[i][j] = (i == j) ? 0 : INF;
        }
    }
    for (int i = 1; i <= tot; i += 2) {
        int u = edges[i].to;
        int v = edges[i ^ 1].to;
        dis[u][v] = dis[v][u] = 1;
    }
    for (int k = 1; k <= n; k++) {
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                dis[i][j] = min(dis[i][j], dis[i][k] + dis[k][j]);
            }
        }
    }
}

struct Spaceship {
    int x, a, f, p;
};

struct Base {
    int x, d, g;
};

int n, m, s, b, k;
Spaceship ships[MAXN];
Base bases[MAXN];
int g[MAXN];
long long maxProfit[MAXN];

void dfs(int u, vector<int>& path, bitset<MAXN>& visited) {
    visited[u] = true;
    path.push_back(u);
    for (int v = g[u]; v; v = g[v]) {
        if (!visited[v]) {
            dfs(v, path, visited);
        }
    }
}

