int calc(string s) {
    int minx = 0, maxx = 0, miny = 0, maxy = 0;
    int x = 0, y = 0;

    for (char c : s) {
        if (c == 'W') y++;
        if (c == 'S') y--;
        if (c == 'A') x--;
        if (c == 'D') x++;

        minx = min(minx, x);
        maxx = max(maxx, x);
        miny = min(miny, y);
        maxy = max(maxy, y);
    }

    return (maxx - minx + 1) * (maxy - miny + 1);
}

