    vector<vector<int>> possible(N);
    for (int i = 0; i < n; i++) {
        possible[mem[i].first.first].push_back(i);
    }

    set<int> assigned;
    for (int i = 1; i <= n; i++) {
        vector<int> can;
        for (auto j : possible[i]) {
            if (assigned.find(mem[j].second) != assigned.end()) {
                continue;
            }
            can.push_back(j);
        }

        if (can.size() > 1) {
            return false;
        }
        if (can.size() == 1) {
            assigned.insert(mem[can[0]].second);
            seq[i - 1] = mem[can[0]].second;
        }
    }

    return true;
}

